import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class StdDateFormat__format_TriageGen1Test {

    /**
     * Helper to invoke the protected _format method using reflection.
     */
    private void invokeFormat(StdDateFormat formatter, TimeZone tz, Locale loc, Date date, StringBuffer buffer) throws Exception {
        Method method = StdDateFormat.class.getDeclaredMethod("_format", TimeZone.class, Locale.class, Date.class, StringBuffer.class);
        method.setAccessible(true);
        method.invoke(formatter, tz, loc, date, buffer);
    }

    @Test
    public void testFormatWithUTCAndNoColon() throws Exception {
        StdDateFormat formatter = new StdDateFormat();
        formatter.withColonInTimeZone(false);

        // 2023-10-05 14:30:05.123 UTC
        Calendar cal = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
        cal.set(2023, Calendar.OCTOBER, 5, 14, 30, 5);
        cal.set(Calendar.MILLISECOND, 123);
        Date date = cal.getTime();

        StringBuffer buffer = new StringBuffer();
        invokeFormat(formatter, TimeZone.getTimeZone("UTC"), Locale.US, date, buffer);

        // Expected: 2023-10-05T14:30:05.123+0000
        assertEquals("2023-10-05T14:30:05.123+0000", buffer.toString());
    }










}

